/* From Uiverse.io by Dashrath-Sharma  - Tags: material design, animation, 3d, white, black, button, simple button */
.__UIV_SCOPE__ .button {
  box-shadow: -5px -5px 15px #444, 5px 5px 15px #222, inset 5px 5px 15px #444,
    inset -5px -5px 15px #222;
}

.__UIV_SCOPE__ .button {
  cursor: pointer;
  position: relative;
  font-size: 17px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5em 4.5em;
  border-radius: 15px;
  border: none;
  font-weight: bold;
  transition: 0.5s;
  z-index: 1;
}
.__UIV_SCOPE__ .button:active {
  transform: scale(0.8);
}
.__UIV_SCOPE__ .button:active::before {
  transform: translateY(-10px);
}

.__UIV_SCOPE__ .button > svg {
  width: 15px;
  height: 15px;
  margin-right: 5px;
}

.__UIV_SCOPE__ .button::before,
.__UIV_SCOPE__ .button::after {
  content: "";
  position: absolute;
  transition: 0.2s;
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
  backdrop-filter: blur(2.5px);
  -webkit-backdrop-filter: blur(2.5px);
  border: 1px solid rgba(255, 255, 255, 0.58);
  z-index: -1;
}

.__UIV_SCOPE__ .button::after {
  width: 90%;
  height: 68%;
}

.__UIV_SCOPE__ .button::before {
  width: 99%;
  height: 90%;
}
